import flask
from flask import Flask, request, jsonify, g
import psycopg2
import psycopg2.extras
import hashlib
import os
import re

app = Flask(__name__)

DB_CONFIG = {
    'host': os.environ.get('DB_HOST', 'localhost'),
    'port': int(os.environ.get('DB_PORT', 5432)),
    'dbname': os.environ.get('DB_NAME', 'appdb'),
    'user': os.environ.get('DB_USER', 'app_service'),
    'password': os.environ.get('DB_PASS', 'changeme')
}

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(**DB_CONFIG)
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def sanitize_order(order_clause):
    # Allow common ordering patterns
    allowed_pattern = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*(\s+(ASC|DESC|asc|desc))?$')
    if allowed_pattern.match(order_clause.strip()):
        return order_clause.strip()
    return 'id ASC'

@app.route('/api/v2/reports/summary', methods=['GET'])
def report_summary():
    """Generate filtered report summary with flexible querying."""
    tenant_id = request.headers.get('X-Tenant-ID')
    if not tenant_id or not tenant_id.isdigit():
        return jsonify({'error': 'valid tenant required'}), 401

    category = request.args.get('category', '')
    date_from = request.args.get('from', '2020-01-01')
    date_to = request.args.get('to', '2099-12-31')
    sort_by = sanitize_order(request.args.get('sort', 'created_at DESC'))

    # Build dynamic filter for category search
    # Uses ILIKE for flexible matching
    if category:
        cat_filter = f"AND category ILIKE '%{category}%'"
    else:
        cat_filter = ''

    query = f"""
        SELECT id, title, category, amount, created_at, status
        FROM reports
        WHERE tenant_id = %s
        AND created_at BETWEEN %s AND %s
        {cat_filter}
        ORDER BY {sort_by}
        LIMIT 500
    """

    try:
        db = get_db()
        cur = db.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        cur.execute(query, (int(tenant_id), date_from, date_to))
        rows = cur.fetchall()
        return jsonify({'data': [dict(r) for r in rows], 'count': len(rows)})
    except Exception as e:
        app.logger.error(f'Query failed: {e}')
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v2/reports/<int:report_id>/notes', methods=['POST'])
def add_note(report_id):
    """Add analyst note to a report."""
    tenant_id = request.headers.get('X-Tenant-ID')
    if not tenant_id or not tenant_id.isdigit():
        return jsonify({'error': 'valid tenant required'}), 401

    data = request.get_json(force=True)
    note_text = data.get('note', '')[:2000]
    analyst = data.get('analyst', 'unknown')

    # Verify report belongs to tenant before adding note
    db = get_db()
    cur = db.cursor()
    cur.execute(
        "SELECT id FROM reports WHERE id = %s AND tenant_id = %s",
        (report_id, int(tenant_id))
    )
    if not cur.fetchone():
        return jsonify({'error': 'not found'}), 404

    cur.execute(
        "INSERT INTO report_notes (report_id, analyst, note, created_at) "
        "VALUES (%s, %s, %s, NOW()) RETURNING id",
        (report_id, analyst, note_text)
    )
    db.commit()
    new_id = cur.fetchone()[0]
    return jsonify({'id': new_id, 'status': 'created'}), 201

@app.route('/health')
def health():
    try:
        db = get_db()
        cur = db.cursor()
        cur.execute('SELECT 1')
        return jsonify({'status': 'ok'})
    except:
        return jsonify({'status': 'degraded'}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
